// HostUpdates What the last updates read found on a server or the panel's own (D-133). Read from apt's package lists and stamps, Docker and /var/run/reboot-required; nothing is installed.
type HostUpdates struct {
	// CheckedAt When the last read ran, whether or not it worked.
	CheckedAt time.Time `json:"checked_at"`
	Docker    struct {
		// Advisories Docker's published security advisories that affect the running engine; none for docker.io.
		Advisories []struct {
			// FixedIn The first engine release that fixes it.
			FixedIn string `json:"fixed_in"`

			// Id The GitHub advisory ID (GHSA-…).
			Id       string                              `json:"id"`
			Severity HostUpdatesDockerAdvisoriesSeverity `json:"severity"`
			Summary  string                              `json:"summary"`
			Url      string                              `json:"url"`
		} `json:"advisories"`

		// Candidate The newer engine apt would install; empty when none is pending.
		Candidate string `json:"candidate"`

		// Package The package that installed it, docker-ce (Docker's) or docker.io (the distribution's, which backports fixes, so Docker's advisories aren't matched against it); empty for neither.
		Package string `json:"package"`

		// Version The engine running now; empty when Docker didn't answer.
		Version string `json:"version"`
	} `json:"docker"`

	// Error Why the last read couldn't run; empty when it did. The rest is what the last read that worked found.
	Error string `json:"error"`

	// Held How many pending updates, security or other, are Docker's packages, which installing updates holds back and updating Docker installs (D-134).
	Held int `json:"held"`

	// ListsUpdatedAt When apt's daily job last downloaded the package lists; null when it never has. Updates published since are not counted.
	ListsUpdatedAt *time.Time `json:"lists_updated_at"`

	// Other Every other pending update, Docker's among them.
	Other int `json:"other"`

	// Packages The pending updates, security first, then by name; at most 500.
	Packages []struct {
		Candidate string `json:"candidate"`

		// Current The installed version; empty for a package the upgrade would add.
		Current  string `json:"current"`
		Name     string `json:"name"`
		Security bool   `json:"security"`
	} `json:"packages"`

	// ReadAt When the last read that worked ran, which everything below comes from; null before one.
	ReadAt *time.Time `json:"read_at"`
	Reboot struct {
		// Packages The packages that asked for the reboot.
		Packages []string   `json:"packages"`
		Required bool       `json:"required"`
		Since    *time.Time `json:"since"`
	} `json:"reboot"`

	// Removals The packages apt would remove to install the pending updates; usually none. At most 500.
	Removals []string `json:"removals"`

	// Security Pending updates from a security origin.
	Security int `json:"security"`

	// Truncated More updates are pending than packages lists.
	Truncated  bool `json:"truncated"`
	Unattended struct {
		// LastError The last run's last error line, when it failed.
		LastError  string                          `json:"last_error"`
		LastResult HostUpdatesUnattendedLastResult `json:"last_result"`

		// LastRunAt When unattended-upgrades last ran; null when it never has.
		LastRunAt     *time.Time `json:"last_run_at"`
		LastSuccessAt *time.Time `json:"last_success_at"`

		// State The unattended-upgrades unit's state; unknown until a read works, when the rest of the report is empty too.
		State HostUpdatesUnattendedState `json:"state"`
	} `json:"unattended"`
}

// HostUpdatesDockerAdvisoriesSeverity defines model for HostUpdates.Docker.Advisories.Severity.
type HostUpdatesDockerAdvisoriesSeverity string

// HostUpdatesUnattendedLastResult defines model for HostUpdates.Unattended.LastResult.
type HostUpdatesUnattendedLastResult string

